import type { Booking } from '@prisma/client';
import { bookingConflict, notFound, validationFailed } from '../../shared/errors.js';
import {
  normalizeLimit,
  normalizeOffset,
  paginated,
  type Page,
} from '../../shared/pagination.js';
import { durationMinutes, isBefore, parseInstant } from '../../shared/time.js';
import { getRoom } from '../rooms/service.js';
import { getUser } from '../users/service.js';
import * as repository from './repository.js';
import { BOOKING_ACTIVE, BOOKING_CANCELLED } from './schema.js';
import type {
  Availability,
  AvailabilityInput,
  AvailabilitySlotData,
  CreateBookingInput,
  ListBookingsInput,
  UpdateBookingInput,
} from './schema.js';

const MIN_BOOKING_MINUTES = 30;
const MAX_BOOKING_MINUTES = 480;
const MAX_AVAILABILITY_DAYS = 31;
const DAY_IN_MINUTES = 1440;

function earliest(a: Date, b: Date): Date {
  return isBefore(a, b) ? a : b;
}

function latest(a: Date, b: Date): Date {
  return isBefore(a, b) ? b : a;
}

function assertDurationInRange(minutes: number, message: string): void {
  if (minutes < MIN_BOOKING_MINUTES || minutes > MAX_BOOKING_MINUTES) {
    throw validationFailed(message, {
      durationMinutes: minutes,
      minMinutes: MIN_BOOKING_MINUTES,
      maxMinutes: MAX_BOOKING_MINUTES,
    });
  }
}

function assertBookingWindow(startsAt: Date, endsAt: Date): void {
  if (isBefore(startsAt, new Date())) {
    throw validationFailed('Booking cannot start in the past', {
      startsAt: startsAt.toISOString(),
    });
  }
  if (!isBefore(startsAt, endsAt)) {
    throw validationFailed('Booking must end after it starts');
  }
  assertDurationInRange(durationMinutes(startsAt, endsAt), 'Booking duration is out of range');
}

async function assertConflictFree(
  roomId: string,
  startsAt: Date,
  endsAt: Date,
  excludeId?: string,
): Promise<void> {
  const conflict = await repository.findOverlapping(roomId, startsAt, endsAt, excludeId);
  if (conflict) {
    throw bookingConflict(conflict.id);
  }
}

function freeSlots(
  booked: Booking[],
  from: Date,
  to: Date,
  minMinutes: number,
): AvailabilitySlotData[] {
  const slots: AvailabilitySlotData[] = [];
  const collect = (startsAt: Date, endsAt: Date): void => {
    if (isBefore(startsAt, endsAt) && durationMinutes(startsAt, endsAt) >= minMinutes) {
      slots.push({ startsAt, endsAt });
    }
  };

  let cursor = from;
  for (const booking of booked) {
    if (!isBefore(cursor, to)) {
      break;
    }
    const occupiedFrom = latest(booking.startsAt, from);
    if (isBefore(cursor, occupiedFrom)) {
      collect(cursor, earliest(occupiedFrom, to));
    }
    cursor = latest(cursor, booking.endsAt);
  }
  if (isBefore(cursor, to)) {
    collect(cursor, to);
  }
  return slots;
}

export async function createBooking(input: CreateBookingInput): Promise<Booking> {
